head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.stFocusGrid = false;
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

scwin.code1Sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    // ShowWin(MxGrid_1);
    const sbmOptions2 = {
        id : "sbm_MxDataSet_code2",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    const sbmOptions3 = {
        id : "sbm_MxDataSet_code3",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);

};

scwin.listSync = async function() {
    if (txb_date1.getValue() === "") {
        alert("시작일을 지정하여주십시요");
        return;
    }
    if (txb_date2.getValue() === "") {
        alert("종료일을 지정하여주십시요");
        return;
    }

    const cdCase1 = "&LIST_BZ_TP_CD=" + MxDataSet_code1.getCellData(MxCombo1.Index + 1, "CD_VAL");

    const cdCase2 = "&LIST_PROCS_STAT_CD=" + MxDataSet_code2.getCellData(MxCombo2.Index + 1, "CD_VAL");

    const cdCase3 = "&LD_MKT_TP_CD=" + MxDataSet_code3.getCellData(MxCombo3.Index + 1, "CD_VAL");
    const cdCase4 = "&ISUR_CD=" + ISUR_CD.getValue();
    const cdCase5 = "&DDTM_FROM=" + txb_date1.getValue() + "&DDTM_TO=" + txb_date2.getValue() + "&DDTM_CD=" + MxRadio.getValue();
    const sbmOptions = {
        id : "sbm_MxDataSet_stat",
        action : "/listprocsstat.do",
        ref : "",
        target : "MxDataSet_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_stat_OnLoadCompleted(MxDataSet_stat.getRowCount()); // 구 콜백 연결

};

scwin.logSync = async function(sval) {
    const sbmOptions = {
        id : "sbm_MxDataSet_log",
        action : "/listprocslog.do",
        ref : "",
        target : "MxDataSet_log=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_log_OnLoadCompleted(MxDataSet_log.getRowCount()); // 구 콜백 연결

};

/*---------------------------------------------------------------------------------------------------------*/
scwin.js_com_Isurcd; // 발행사코드
scwin.js_com_Isurnm; // 발행사명

scwin.js_com_market = frame.Provider("/top").ps_market; // 운영관리는 "" 로 처리 상장공시처리에서는 세션으로 처리
if (scwin.js_com_market !== "1" && scwin.js_com_market !== "2") scwin.js_com_market = "";
// if (typeof(js_com_market)=="undefined") {js_com_market = ""; }else{ js_com_market = js_market; }
scwin.js_com_left;
scwin.js_com_top;

$c.cm.IsurTagetPos = function(grdObj, grdObj2, Tg) {
    let cL = 7;
    let cT = 53;
    if (Tg === "G") {
        cL = 3;
        cT = 22;
    }
    scwin.js_com_left = grdObj.style.left;
    scwin.js_com_left = scwin.js_com_left.substring(0, scwin.js_com_left.length - 2);
    scwin.js_com_left = eval(scwin.js_com_left) + cL;
    scwin.js_com_top = grdObj.style.top;
    scwin.js_com_top = scwin.js_com_top.substring(0, scwin.js_com_top.length - 2);
    scwin.js_com_top = eval(scwin.js_com_top) + cT;
};
$c.cm.fn_com_grid_pos = function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; // 발행사코드
    scwin.js_com_Isurnm = grdObj2; // 발행사명
    scwin.IsurTagetPos(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = scwin.js_com_left;
    Grd_com_isur.style.top = scwin.js_com_top;
};
$c.cm.IsurcdSearch = async function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; // 발행사코드
    scwin.js_com_Isurnm = grdObj2; // 발행사명
    scwin.IsurTagetPos(grdObj, grdObj2, 'E');

    const options = {
        id: "ULDCOM00007",
        title: "발행회사검색창",
        type: "pageFramePopup",
        width: "295px",
        height: "400px"
    };

    const data = {};

    const result = await $c.win.openPopup("/common/ULDCOM00007.gfm", options, data);
    // 팝업(ULDCOM00007) 리턴 "코드^명" 을 기존 콜백 계약(isurSearch_Rtn)에 연결
    if (result) {
        $c.cm.isurSearch_Rtn(...String(result).split("^"));
    }
};
$c.cm.isurSearch_Rtn = function(pJongCode, pJongNm) {
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);
};
$c.cm.fn_com_isur_sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/isurcd.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

};
$c.cm.fn_com_isur = async function(grdObj, grdObj2) {
    Grd_com_isur.style.display = "none";
    scwin.fn_com_grid_pos(grdObj, grdObj2);
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    scwin.fn_com_isur_sync();
};
$c.cm.fn_com_Confirm_set = function() {

    const pJongCode = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "ISUR_CD");

    const pJongNm = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "COM_ABBRV");
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);

    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
$c.cm.fn_com_isur_nm = function(keyCode) {
    let cnt = 0;
    const len = scwin.js_com_Isurcd.getValue().length;
    const txtVal = scwin.js_com_Isurcd.getValue().toUpperCase();
    let foColum = 1;
if (len > 1) {
        if (isNaN(txtVal)) {
            foColum = 1;
        } else {
            foColum = 2;
        }
    }
    if (foColum === 1) {
        MxDataSet_com_isur.sort("COM_ABBRV", 0);
        for (let i = 0; i < MxDataSet_com_isur.getRowCount(); i++) {

            let name = MxDataSet_com_isur.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    } else {
        MxDataSet_com_isur.sort("ISUR_CD", 0);
        for (let i = 0; i < MxDataSet_com_isur.getRowCount(); i++) {

            let name = MxDataSet_com_isur.getCellData(i, "ISUR_CD").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    }
// TODO Stage2: 그리드 포커스 전환 필요(구 MxDataSet_com_isur.Rowposition = cnt + 11)
    // TODO Stage2: 그리드 포커스 전환 필요(구 MxDataSet_com_isur.Rowposition = cnt)
};
$c.stockSearch.isNumber = function(sVal) {
    // 숫자인지 확인
    if (('0' < sVal) || ('9' > sVal)) {
        return true;
    } else {
        return false;
    }
};

/*-----------------------------------------------------------------------------------------------------*/
scwin.isur_cd_onblur = function() {

    if (scwin.stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (ISUR_CD.getValue() === "") {
        isur_nm.setValue("");
    }
};

scwin.isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "";
};

scwin.isur_cd_onkeyup = function(e) {
    if (Number(e.keyCode) === 40) {
        // 아래화살표눌렀을때 그리드로 포커스

        Grd_com_isur.Focus();
    } else {
        if (Number(e.keyCode) === 13) {
            scwin.fn_com_Confirm_set();
        } else {
            scwin.fn_com_isur_nm(e.keyCode);
        }
    }
};

scwin.MxDataSet_stat_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");

    MxDataSet_log.removeAll();
};

scwin.MxDataSet_log_OnLoadCompleted = function(rowcount) {

    grid_stat.Focus();
};

scwin.gform_onload = async function() {
    MxRadio.setValue(0);
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    const sbmOptions2 = {
        id : "sbm_MxDataSet_code2",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    const sbmOptions3 = {
        id : "sbm_MxDataSet_code3",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);

    const sbmOptions4 = {
        id : "sbm_MxDataSet_stat",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    scwin.MxDataSet_stat_OnLoadCompleted(MxDataSet_stat.getRowCount()); // 구 콜백 연결

    const sbmOptions5 = {
        id : "sbm_MxDataSet_log",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_log=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    scwin.MxDataSet_log_OnLoadCompleted(MxDataSet_log.getRowCount()); // 구 콜백 연결

    scwin.code1Sync();
    scwin.fn_com_isur(isur_cd, isur_nm); // 발행사Autofill를 위한 스크립트

    toDaySet(txb_date1);

    toDaySet(txb_date2);
};

scwin.btn_sys_search_onclick = function(e) {
    scwin.listSync();
};

scwin.btn_cal_onclick = function(e) {

    popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); // alert('image_2.onclick');

};

scwin.image_1_onclick = function(e) {

    popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); // alert('image_2.onclick');

};

scwin.grid_stat_OnClick = function(row, colid) {

    const sCd = MxDataSet_stat.getCellData(row, "BZ_PROCS_NO");
    scwin.logSync(sCd);
};

scwin.image_6_onclick = function(e) {
    scwin.IsurcdSearch(isur_cd, isur_nm);
};

scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        scwin.fn_com_Confirm_set();
    }
};

scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    scwin.fn_com_Confirm_set();
};

scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

scwin.Grd_com_isur_OnSetFocus = function() {

    scwin.stFocusGrid = true;
};

scwin.Grd_com_isur_OnKillFocus = function() {

    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
